import AppKit
import CryptoKit
import ImageIO
import UniformTypeIdentifiers

/// Turns raw pasteboard data (live, or one of Maccy's saved items) into a `NewItem`.
/// Keeps one plain-text copy plus RTF/HTML for formatting, and drops the rest: UTF-16 duplicates,
/// web archives, browser tokens and file icons.
enum Capture {
    /// Password managers and apps that mark a copy as private or temporary (nspasteboard.org).
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "net.antelle.keeweb",
        "com.typeit4me.clipping", "Pasteboard generator type",
    ]

    static let text = NSPasteboard.PasteboardType.string.rawValue
    static let fileURL = NSPasteboard.PasteboardType.fileURL.rawValue
    static let rtf = NSPasteboard.PasteboardType.rtf.rawValue
    static let html = NSPasteboard.PasteboardType.html.rawValue
    static let png = NSPasteboard.PasteboardType.png.rawValue
    static let tiff = NSPasteboard.PasteboardType.tiff.rawValue

    /// Reads only the types it might keep, so a 27 MB web archive is never pulled into memory.
    static func read(_ pasteboard: NSPasteboard) -> [String: Data]? {
        guard let item = pasteboard.pasteboardItems?.first else { return nil }
        let types = Set(item.types.map(\.rawValue))
        guard types.isDisjoint(with: ignoredTypes) else { return nil }
        var data: [String: Data] = [:]
        if types.contains(fileURL) {
            let urls = (pasteboard.pasteboardItems ?? []).compactMap { $0.string(forType: .fileURL) }
            data[fileURL] = Data(urls.joined(separator: "\n").utf8)
            return data
        }
        for type in [text, rtf, html] where types.contains(type) {
            data[type] = item.data(forType: NSPasteboard.PasteboardType(type))
        }
        if data[text] == nil {
            for type in [png, tiff] where types.contains(type) {
                data[type] = item.data(forType: NSPasteboard.PasteboardType(type))
                break
            }
        }
        return data.isEmpty ? nil : data
    }

    /// Builds the item; image work (decode, hash, HEIC encode) happens here, so call it off the main thread.
    static func item(from data: [String: Data], app: String?) -> NewItem? {
        if let urls = data[fileURL].flatMap({ String(data: $0, encoding: .utf8) }) {
            let files = urls.split(separator: "\n").map(String.init).filter { !$0.isEmpty }
            guard !files.isEmpty else { return nil }
            return NewItem(kind: .file, text: nil, rtf: nil, html: nil, files: files, app: app)
        }
        if let string = data[text].flatMap({ String(data: $0, encoding: .utf8) }),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return NewItem(kind: .text, text: string, rtf: data[rtf], html: data[html], app: app)
        }
        if let image = data[png] ?? data[tiff], let stored = storeImage(image) {
            return NewItem(kind: .image, text: nil, rtf: nil, html: nil,
                           imageHash: stored.hash, imageSize: stored.size, app: app)
        }
        return nil
    }

    /// Writes the image as HEIC (quality 0.9) plus a small thumbnail, named by a hash of its pixels,
    /// so the same picture copied as TIFF and as PNG is stored once.
    static func storeImage(_ data: Data) -> (hash: String, size: CGSize)? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil),
              let pixels = image.dataProvider?.data as Data? else { return nil }
        var hasher = SHA256()
        hasher.update(data: Data("\(image.width)x\(image.height)".utf8))
        hasher.update(data: pixels)
        let hash = hasher.finalize().prefix(16).map { String(format: "%02x", $0) }.joined()
        let size = CGSize(width: image.width, height: image.height)

        let full = Store.imageURL(hash)
        if !FileManager.default.fileExists(atPath: full.path) {
            guard write(image, to: full, quality: 0.9) else { return nil }
        }
        let thumb = Store.thumbURL(hash)
        if !FileManager.default.fileExists(atPath: thumb.path) {
            let options: [CFString: Any] = [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceThumbnailMaxPixelSize: 240,
                kCGImageSourceCreateThumbnailWithTransform: true,
            ]
            if let small = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) {
                _ = write(small, to: thumb, quality: 0.75)
            }
        }
        return (hash, size)
    }

    private static func write(_ image: CGImage, to url: URL, quality: Double) -> Bool {
        guard let dest = CGImageDestinationCreateWithURL(url as CFURL, UTType.heic.identifier as CFString, 1, nil) else { return false }
        CGImageDestinationAddImage(dest, image, [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary)
        return CGImageDestinationFinalize(dest)
    }
}

/// Polls the general pasteboard's change count, the only signal macOS gives, and saves new copies.
final class Watcher {
    private let store: Store
    private let onChange: () -> Void
    private var timer: Timer?
    private var lastChange = NSPasteboard.general.changeCount
    private let work = DispatchQueue(label: "stash.capture", qos: .utility)

    init(store: Store, onChange: @escaping () -> Void) {
        self.store = store
        self.onChange = onChange
    }

    func start() {
        let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        timer.tolerance = 0.2
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Called after Stash itself writes the pasteboard, so its own copy isn't recorded again.
    func skipCurrent() { lastChange = NSPasteboard.general.changeCount }

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount
        guard let data = Capture.read(pasteboard) else { return }
        let app = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        work.async { [store, onChange] in
            let saved = autoreleasepool { Capture.item(from: data, app: app).map(store.save) ?? false }
            // Decoding a big screenshot grows the heap by its raw size; give those pages back now.
            if data[Capture.png] != nil || data[Capture.tiff] != nil { malloc_zone_pressure_relief(nil, 0) }
            if saved { DispatchQueue.main.async(execute: onChange) }
        }
    }
}
